"use client";

import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { 
  Wallet, ArrowUpCircle, ArrowDownCircle, Search, 
  Plus, Filter, X, Target, Heart, Users, BookOpen, 
  ChevronRight, Info, AlertCircle
} from "lucide-react";
import TourGuide from "@/components/TourGuide";
import { createGeneralTrx, createEventBudget, createEventTrx, createBukuKas } from "@/lib/actions";

const formatIDR = (val: number) => new Intl.NumberFormat("id-ID", { style: "currency", currency: "IDR", maximumFractionDigits: 0 }).format(val);

export default function KeuanganClient({ ledgers, events, prokers }: { ledgers: any[], events: any[], prokers: any[] }) {
  const [activeTab, setActiveTab] = useState<'general' | 'events'>('general');
  const [selectedLedgerId, setSelectedLedgerId] = useState<number>(ledgers[0]?.id || 1);
  const [isClient, setIsClient] = useState(false); 
  
  // STATE MODAL & FORM
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [modalType, setModalType] = useState<'general_in' | 'general_out' | 'new_event' | 'event_trx' | 'new_ledger'>('general_in');
  const [selectedEventId, setSelectedEventId] = useState<number | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  
  const [formData, setFormData] = useState<any>({ 
    title: "", amount: "", date: new Date().toISOString().split('T')[0], 
    category: "Umum", pic: "", prokerId: "", isSubsidi: false, 
    bukuKasId: "", ledgerName: "", ledgerDesc: "", fromBukuId: ""
  });

  useEffect(() => { setIsClient(true); }, []);

  // DATA BUKU KAS TERPILIH
  const currentLedger = ledgers.find(l => l.id === selectedLedgerId) || ledgers[0];
  const transactions = currentLedger?.transaksi || [];

  const totalMasuk = transactions.filter((t:any) => t.tipe === 'PEMASUKAN').reduce((acc:any, curr:any) => acc + curr.nominal, 0);
  const totalKeluar = transactions.filter((t:any) => t.tipe === 'PENGELUARAN').reduce((acc:any, curr:any) => acc + curr.nominal, 0);
  const saldo = totalMasuk - totalKeluar;

  const handleOpenGeneralModal = (type: 'in' | 'out') => {
    setModalType(type === 'in' ? 'general_in' : 'general_out');
    setFormData({ ...formData, title: "", amount: "", date: new Date().toISOString().split('T')[0], bukuKasId: selectedLedgerId });
    setIsModalOpen(true);
  };

  const handleSubmit = async () => {
    setIsSubmitting(true);
    const data = new FormData();
    Object.entries(formData).forEach(([key, val]) => data.append(key, String(val)));

    let result;
    try {
        if (modalType === 'general_in' || modalType === 'general_out') {
            data.append("type", modalType === 'general_in' ? "PEMASUKAN" : "PENGELUARAN");
            data.append("bukuKasId", String(selectedLedgerId));
            result = await createGeneralTrx(data);
        } 
        else if (modalType === 'new_ledger') {
            data.append("nama", formData.ledgerName);
            data.append("deskripsi", formData.ledgerDesc);
            result = await createBukuKas(data);
        }
        else if (modalType === 'new_event') {
            result = await createEventBudget(data);
        } 
        else if (modalType === 'event_trx' && selectedEventId) {
            data.append("eventId", selectedEventId.toString());
            result = await createEventTrx(data);
        }

        if (result?.success) {
            setIsModalOpen(false);
            window.location.reload(); 
        } else { alert("Error: " + result?.message); }
    } catch (e) { alert("Terjadi kesalahan."); } finally { setIsSubmitting(false); }
  };

  return (
    <div className="h-[calc(100vh-140px)] flex flex-col gap-6 font-sans">
      <div className="flex flex-col md:flex-row justify-between items-end gap-4 shrink-0 px-4 md:px-0">
         <div>
            <h1 className="text-3xl font-bold text-slate-900 dark:text-white tracking-tight flex items-center gap-3">Sistem Keuangan OSIS <span className="text-2xl p-2 bg-blue-100 dark:bg-blue-900/30 rounded-full">📊</span></h1>
            <p className="text-slate-500 dark:text-slate-400 text-sm font-medium mt-1">Kelola pembukuan terpisah secara profesional.</p>
         </div>
         <div className="flex bg-slate-100 dark:bg-[#1e293b] p-1 rounded-xl border border-slate-200 dark:border-white/10">
            <button onClick={() => setActiveTab('general')} className={`px-6 py-2.5 rounded-lg text-xs font-bold transition-all ${activeTab === 'general' ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-white shadow-sm' : 'text-slate-500'}`}>Buku Kas (Multi-Ledger)</button>
            <button onClick={() => setActiveTab('events')} className={`px-6 py-2.5 rounded-lg text-xs font-bold transition-all ${activeTab === 'events' ? 'bg-white dark:bg-slate-700 text-purple-600 dark:text-white shadow-sm' : 'text-slate-500'}`}>Anggaran Kegiatan</button>
         </div>
      </div>

      {activeTab === 'general' && (
        <div className="flex flex-col lg:flex-row gap-6 flex-1 overflow-hidden">
            {/* SIDEBAR: DAFTAR BUKU KAS */}
            <div className="w-full lg:w-72 flex flex-col gap-4 shrink-0 bg-white dark:bg-[#0f172a] border border-slate-200 dark:border-white/5 rounded-2xl p-5 shadow-sm overflow-hidden">
                <div className="flex justify-between items-center mb-2">
                    <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest">Daftar Buku Kas</h3>
                    <button onClick={() => { setModalType('new_ledger'); setIsModalOpen(true); }} className="p-1.5 bg-blue-600 text-white rounded-lg hover:scale-105 transition-all"><Plus size={14}/></button>
                </div>
                <div className="flex-1 overflow-y-auto space-y-2 custom-scrollbar">
                    {ledgers.map(l => (
                        <div key={l.id} onClick={() => setSelectedLedgerId(l.id)} className={`p-4 rounded-xl cursor-pointer transition-all border group relative ${selectedLedgerId === l.id ? 'bg-blue-50/50 dark:bg-blue-500/10 border-blue-200 dark:border-blue-500/30' : 'bg-transparent border-transparent hover:bg-slate-50 dark:hover:bg-white/5'}`}>
                            {selectedLedgerId === l.id && <motion.div layoutId="ledgerActive" className="absolute left-0 top-3 bottom-3 w-1 bg-blue-600 rounded-r-full" />}
                            <div className="flex items-center gap-3">
                                <div className={`p-2 rounded-lg ${selectedLedgerId === l.id ? 'bg-blue-600 text-white' : 'bg-slate-100 dark:bg-white/5 text-slate-400'}`}>
                                    {l.icon === 'Heart' ? <Heart size={16}/> : l.icon === 'Users' ? <Users size={16}/> : <Wallet size={16}/>}
                                </div>
                                <div className="min-w-0 flex-1">
                                    <h4 className={`text-xs font-bold truncate ${selectedLedgerId === l.id ? 'text-blue-900 dark:text-blue-100' : 'text-slate-700 dark:text-slate-300'}`}>{l.nama}</h4>
                                    <p className="text-[10px] font-medium text-slate-400 truncate">{l.deskripsi}</p>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* MAIN AREA: TRANSAKSI BUKU TERPILIH */}
            <div className="flex-1 flex flex-col gap-6 overflow-hidden">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div className="bg-white dark:bg-[#0f172a] p-5 rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm">
                        <p className="text-[10px] uppercase font-bold text-slate-500 tracking-widest mb-1">Saldo {currentLedger?.nama}</p>
                        <h2 className="text-2xl font-bold text-slate-900 dark:text-white">{formatIDR(saldo)}</h2>
                    </div>
                    <div className="bg-white dark:bg-[#0f172a] p-5 rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm">
                        <p className="text-[10px] uppercase font-bold text-emerald-500 tracking-widest mb-1">Pemasukan</p>
                        <h2 className="text-xl font-bold text-emerald-600">{formatIDR(totalMasuk)}</h2>
                    </div>
                    <div className="bg-white dark:bg-[#0f172a] p-5 rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm">
                        <p className="text-[10px] uppercase font-bold text-rose-500 tracking-widest mb-1">Pengeluaran</p>
                        <h2 className="text-xl font-bold text-rose-600">{formatIDR(totalKeluar)}</h2>
                    </div>
                </div>

                <div className="flex-1 bg-white dark:bg-[#0f172a] rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm flex flex-col overflow-hidden">
                    <div className="px-6 py-4 flex justify-between items-center border-b border-slate-100 dark:border-white/5 bg-slate-50/50 dark:bg-transparent">
                        <h3 className="text-sm font-bold text-slate-800 dark:text-white tracking-tight">Riwayat: {currentLedger?.nama}</h3>
                        <div className="flex gap-2">
                            <button onClick={() => handleOpenGeneralModal('in')} className="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-[11px] font-bold flex items-center gap-2 shadow-lg shadow-emerald-500/20 transition-all active:scale-95"><Plus size={14}/> Masuk</button>
                            <button onClick={() => handleOpenGeneralModal('out')} className="px-4 py-2 bg-rose-600 hover:bg-rose-700 text-white rounded-lg text-[11px] font-bold flex items-center gap-2 shadow-lg shadow-rose-500/20 transition-all active:scale-95"><ArrowDownCircle size={14}/> Keluar</button>
                        </div>
                    </div>
                    <div className="flex-1 overflow-auto custom-scrollbar">
                        <table className="w-full text-left border-collapse">
                            <thead className="bg-slate-50 dark:bg-white/5 sticky top-0 z-10 border-b border-slate-100 dark:border-white/10">
                                <tr>
                                    <th className="p-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest pl-6">Tanggal</th>
                                    <th className="p-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">Keterangan</th>
                                    <th className="p-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest text-right pr-6">Nominal</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-50 dark:divide-white/5">
                                {transactions.length === 0 ? (
                                    <tr><td colSpan={3} className="p-12 text-center text-slate-400 text-xs font-medium">Belum ada transaksi di buku ini</td></tr>
                                ) : (
                                    transactions.map((t:any) => (
                                        <tr key={t.id} className="hover:bg-slate-50/80 dark:hover:bg-white/5 transition-colors">
                                            <td className="p-4 text-[11px] font-medium text-slate-500 pl-6">{new Date(t.tanggal).toLocaleDateString('id-ID', { day:'2-digit', month:'short' })}</td>
                                            <td className="p-4"><p className="text-sm font-bold text-slate-800 dark:text-slate-200">{t.judul}</p><p className="text-[10px] font-medium text-slate-400 uppercase tracking-tighter">{t.kategori}</p></td>
                                            <td className={`p-4 text-right font-bold pr-6 ${t.tipe === 'PEMASUKAN' ? 'text-emerald-600' : 'text-rose-600'}`}>{t.tipe === 'PEMASUKAN' ? '+' : '-'} {formatIDR(t.nominal)}</td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </div>
      )}

      {activeTab === 'events' && (
        <div className="flex-1 overflow-y-auto p-4 md:p-0 custom-scrollbar">
            {/* UI LAMA ANGGARAN TETAP DI SINI (Disesuaikan sedikit) */}
            <div className="bg-white dark:bg-[#0f172a] rounded-2xl border border-slate-200 dark:border-white/5 flex flex-col h-full overflow-hidden">
                <div className="p-6 border-b border-slate-100 dark:border-white/5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-slate-50/30">
                    <div>
                        <h3 className="text-lg font-bold text-slate-900 dark:text-white">Anggaran Program Kerja</h3>
                        <p className="text-xs font-medium text-slate-500">Monitoring realisasi dana per kegiatan.</p>
                    </div>
                    <button onClick={() => { setModalType('new_event'); setIsModalOpen(true); }} className="px-5 py-2.5 bg-purple-600 text-white rounded-xl font-bold text-xs shadow-lg shadow-purple-500/20 transition-all active:scale-95 flex items-center gap-2"><Plus size={16}/> Alokasi Anggaran</button>
                </div>
                <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6 overflow-y-auto flex-1">
                    {events.map(ev => {
                        const percent = ev.budget > 0 ? Math.round((ev.used / ev.budget) * 100) : 0;
                        return (
                            <div key={ev.id} className="rounded-2xl border p-5 bg-white dark:bg-white/5 border-slate-200 dark:border-white/10 hover:shadow-md transition-all">
                                <div className="flex justify-between items-start mb-4">
                                    <div className="p-3 bg-purple-100 dark:bg-purple-500/20 text-purple-600 rounded-xl"><Target size={24}/></div>
                                    <span className="text-[9px] font-bold px-2 py-0.5 rounded-full bg-blue-50 text-blue-600 border border-blue-100 uppercase">{ev.status}</span>
                                </div>
                                <h3 className="text-base font-bold text-slate-900 dark:text-white mb-1">{ev.name}</h3>
                                <div className="space-y-2 mb-6 bg-slate-50 dark:bg-white/5 p-4 rounded-xl border border-slate-100 dark:border-white/5">
                                    <div className="flex justify-between text-[10px] font-bold uppercase tracking-wider"><span className="text-slate-500">Realisasi ({percent}%)</span><span className="text-purple-600">{formatIDR(ev.used)}</span></div>
                                    <div className="w-full h-1.5 bg-slate-200 dark:bg-white/10 rounded-full overflow-hidden"><div className="h-full bg-purple-500 transition-all duration-1000" style={{ width: `${percent}%` }}></div></div>
                                    <div className="text-right text-[10px] font-bold text-emerald-600">Total Budget: {formatIDR(ev.budget)}</div>
                                </div>
                                <button onClick={() => { setSelectedEventId(ev.id); setModalType('event_trx'); setIsModalOpen(true); }} className="w-full py-2.5 rounded-xl border border-dashed border-slate-300 text-slate-400 hover:text-purple-600 hover:bg-purple-50 text-[11px] font-bold transition-all flex items-center justify-center gap-2"><Plus size={14}/> Catat Pengeluaran</button>
                            </div>
                        )
                    })}
                </div>
            </div>
        </div>
      )}

      {/* === MODAL UNIVERSAL === */}
      <AnimatePresence>
        {isModalOpen && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setIsModalOpen(false)} className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" />
                <motion.div initial={{ scale: 0.95, opacity: 0, y: 20 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.95, opacity: 0, y: 20 }} className="relative w-full max-w-md bg-white dark:bg-[#0f172a] rounded-2xl shadow-2xl overflow-hidden border border-white/10">
                    <div className="p-6 border-b flex justify-between items-center bg-slate-50 dark:bg-white/5">
                        <div>
                            <h2 className="text-base font-bold text-slate-800 dark:text-white uppercase tracking-tight">
                                {modalType === 'general_in' ? 'Uang Masuk' : modalType === 'general_out' ? 'Uang Keluar' : modalType === 'new_ledger' ? 'Buku Kas Baru' : 'Alokasi Dana'}
                            </h2>
                            <p className="text-[10px] font-medium text-slate-400 uppercase tracking-widest mt-0.5">{currentLedger?.nama}</p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-lg transition-colors"><X size={18}/></button>
                    </div>

                    <div className="p-7 space-y-5">
                        {modalType === 'new_ledger' ? (
                            <>
                                <div className="space-y-2"><label className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">Nama Buku Kas</label><input type="text" value={formData.ledgerName} onChange={e => setFormData({...formData, ledgerName: e.target.value})} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-blue-500 dark:text-white text-xs font-bold" placeholder="Contoh: Dana Sosial" /></div>
                                <div className="space-y-2"><label className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">Deskripsi Singkat</label><input type="text" value={formData.ledgerDesc} onChange={e => setFormData({...formData, ledgerDesc: e.target.value})} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-blue-500 dark:text-white text-xs font-bold" placeholder="..." /></div>
                            </>
                        ) : modalType === 'new_event' ? (
                            <>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">Pilih Proker</label>
                                    <select value={formData.prokerId} onChange={e => setFormData({...formData, prokerId: e.target.value})} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-purple-500 dark:text-white text-xs font-bold transition-all">
                                        <option value="">-- Buat Proker Baru --</option>
                                        {prokers.map(p => (<option key={p.id} value={p.id}>{p.nama}</option>))}
                                    </select>
                                </div>
                                <div className="space-y-2 p-4 bg-amber-50 dark:bg-amber-500/10 rounded-xl border border-amber-100 dark:border-amber-500/20">
                                    <div className="flex items-center justify-between">
                                        <div className="flex items-center gap-3">
                                            <div className={`p-2 rounded-lg ${formData.isSubsidi ? 'bg-amber-500 text-white' : 'bg-slate-200 dark:bg-white/10 text-slate-400'}`}><Wallet size={16} /></div>
                                            <div>
                                                <p className="text-[10px] font-bold text-slate-900 dark:text-white uppercase tracking-tight">Ambil dari Buku Kas?</p>
                                                <p className="text-[9px] font-medium text-slate-500 leading-tight">Pilih dompet sumber subsidi.</p>
                                            </div>
                                        </div>
                                        <button type="button" onClick={() => setFormData({...formData, isSubsidi: !formData.isSubsidi})} className={`w-10 h-5 rounded-full transition-all relative ${formData.isSubsidi ? 'bg-amber-500' : 'bg-slate-300 dark:bg-white/10'}`}><div className={`absolute top-0.5 w-4 h-4 bg-white rounded-full transition-all ${formData.isSubsidi ? 'left-5.5' : 'left-0.5'}`} /></button>
                                    </div>
                                    {formData.isSubsidi && (
                                        <select value={formData.fromBukuId} onChange={e => setFormData({...formData, fromBukuId: e.target.value})} className="mt-3 w-full px-3 py-2 rounded-lg bg-white dark:bg-slate-800 border border-amber-200 outline-none text-[10px] font-bold">
                                            <option value="">-- Pilih Buku Kas Sumber --</option>
                                            {ledgers.map(l => (<option key={l.id} value={l.id}>{l.nama}</option>))}
                                        </select>
                                    )}
                                </div>
                                <div className="space-y-2"><label className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">Jumlah Dana (Rp)</label><input type="number" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-blue-500 dark:text-white text-xs font-bold" placeholder="0" /></div>
                            </>
                        ) : (
                            <>
                                <div className="space-y-2"><label className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">Keterangan Transaksi</label><input autoFocus type="text" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-blue-500 dark:text-white text-xs font-bold" placeholder="..." /></div>
                                <div className="space-y-2"><label className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">Nominal (Rp)</label><input type="number" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-blue-500 dark:text-white text-xs font-bold" placeholder="0" /></div>
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="space-y-2"><label className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">Tanggal</label><input type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none text-[11px] font-bold dark:text-white" /></div>
                                    <div className="space-y-2"><label className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">Kategori</label><input type="text" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none text-[11px] font-bold dark:text-white" /></div>
                                </div>
                            </>
                        )}
                    </div>

                    <div className="p-6 border-t border-slate-100 dark:border-white/5 bg-slate-50/50 dark:bg-white/5 flex justify-end gap-3">
                        <button onClick={() => setIsModalOpen(false)} disabled={isSubmitting} className="px-5 py-2.5 rounded-xl text-xs font-bold text-slate-500 hover:bg-slate-200 dark:hover:bg-white/5 transition-colors">Batal</button>
                        <button onClick={handleSubmit} disabled={isSubmitting} className="px-7 py-2.5 rounded-xl bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold shadow-lg shadow-blue-500/20 transition-all active:scale-95">
                            {isSubmitting ? "Memproses..." : "Konfirmasi"}
                        </button>
                    </div>
                </motion.div>
            </div>
        )}
      </AnimatePresence>

      <style jsx global>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
        .dark .custom-scrollbar::-webkit-scrollbar-thumb { background: #334155; }
      `}</style>
    </div>
  );
}
